import AppKit

/// Short, quiet cues bundled with the app (generated by `scripts/make-sound-cues.py`). Played locally, never looped.
@MainActor
public final class AmbientSoundEffects {
    public enum Cue: String, CaseIterable { case listen, send, attention, complete, error }

    /// The files peak at half scale; this keeps every cue well under a spoken reply.
    static let volume: Float = 0.18

    public var isEnabled = true {
        didSet { if !isEnabled { sounds.values.forEach { $0.stop() } } }
    }
    private(set) var sounds: [Cue: NSSound] = [:]

    public init() {
        for cue in Cue.allCases {
            guard let url = Bundle.module.url(forResource: cue.rawValue, withExtension: "wav", subdirectory: "Sounds"),
                  let sound = NSSound(contentsOf: url, byReference: false) else { continue }
            sound.volume = Self.volume
            sounds[cue] = sound
        }
    }

    public func play(_ cue: Cue) {
        guard isEnabled else { return }
        sounds.values.forEach { $0.stop() }
        let started = sounds[cue]?.play() ?? false
        NSLog("Ambient sound cue: %@ started=%@", cue.rawValue, String(started))
    }
}
